selector_to_html = {"a[href=\"#the-heuristics-config-utils-py-file\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.2 The <code class=\"docutils literal notranslate\"><span class=\"pre\">heuristics_config_utils.py</span></code> file<a class=\"headerlink\" href=\"#the-heuristics-config-utils-py-file\" title=\"Link to this heading\">#</a></h3><p>In the <code class=\"docutils literal notranslate\"><span class=\"pre\">heuristics_config_utils.py</span></code> file, You will configure the <code class=\"docutils literal notranslate\"><span class=\"pre\">triton.heuristics</span></code> parameters.\nYou can  refer to <code class=\"docutils literal notranslate\"><span class=\"pre\">src/flag_gems/runtime/backend/_nvidia/heuristics_config_utils.py</span></code>\nfor an example.</p>", "a[href=\"#the-tune-configs-yaml-file\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.3 The <code class=\"docutils literal notranslate\"><span class=\"pre\">tune_configs.yaml</span></code> file<a class=\"headerlink\" href=\"#the-tune-configs-yaml-file\" title=\"Link to this heading\">#</a></h3><p>In the <code class=\"docutils literal notranslate\"><span class=\"pre\">tune_configs.yaml</span></code> file, you can customize <code class=\"docutils literal notranslate\"><span class=\"pre\">triton.autotune</span></code> parameters.\nSimilarly, you can refer to <code class=\"docutils literal notranslate\"><span class=\"pre\">src/flag_gems/runtime/backend/_nvidia/tune_configs.yaml</span></code>\nfor an example.</p>", "a[href=\"#the-ops-directory\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.4 The <code class=\"docutils literal notranslate\"><span class=\"pre\">ops</span></code> directory<a class=\"headerlink\" href=\"#the-ops-directory\" title=\"Link to this heading\">#</a></h3><p>The <code class=\"docutils literal notranslate\"><span class=\"pre\">ops</span></code> directory is where vendor-customized operator implementations are stored.\nFor instance, if you want to create a custom <code class=\"docutils literal notranslate\"><span class=\"pre\">add</span></code> operator, you will place the implementation\nin <code class=\"docutils literal notranslate\"><span class=\"pre\">ops/add.py</span></code>. Following that, you should update the <code class=\"docutils literal notranslate\"><span class=\"pre\">ops/__init__.py</span></code> accordingly\nas shown in the following example. The <code class=\"docutils literal notranslate\"><span class=\"pre\">__all__</span></code> list in the <code class=\"docutils literal notranslate\"><span class=\"pre\">ops/__init__.py</span></code> file\nensures that your implementation for <code class=\"docutils literal notranslate\"><span class=\"pre\">add</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">gelu</span></code> is accessible from external\npackages.</p>", "a[href=\"#about-init-py-file\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.1 About <code class=\"docutils literal notranslate\"><span class=\"pre\">__init__.py</span></code> file<a class=\"headerlink\" href=\"#about-init-py-file\" title=\"Link to this heading\">#</a></h3><p>An easy way to to create this file is to copy one from existing vendors\n(say <code class=\"docutils literal notranslate\"><span class=\"pre\">src/flag_gems/runtime/backend/_nvidia/__init__.py</span></code>).\nAfter having created your <code class=\"docutils literal notranslate\"><span class=\"pre\">__init__.py</span></code> file, the <strong>only change</strong> you need to make is\nto configure the properties for the <code class=\"docutils literal notranslate\"><span class=\"pre\">VendorDescriptor</span></code> class:</p>", "a[href=\"#create-a-backend-directory\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. Create a backend directory<a class=\"headerlink\" href=\"#create-a-backend-directory\" title=\"Link to this heading\">#</a></h2><p>All vendor-specific optimization code reside in the <code class=\"docutils literal notranslate\"><span class=\"pre\">src/flag_gems/runtime/backend</span></code> directory.\nYou can start by creating a folder for identification under this directory,\nfollowing the naming pattern <code class=\"docutils literal notranslate\"><span class=\"pre\">&lt;_vendor-name&gt;</span></code>. As an example, all NVIDIA-specific customization\ncan be found at <code class=\"docutils literal notranslate\"><span class=\"pre\">src/flag_gems/runtime/backend/_nvidia</span></code>.</p>", "a[href=\"#introduction\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. Introduction<a class=\"headerlink\" href=\"#introduction\" title=\"Link to this heading\">#</a></h2><p>The <code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems</span></code> accelerated operators library from the <em>FlagGems</em> project can be used on multiple backends.\nIf you are a chip vendor and wish to contribute backend-specific optimizations for your hardware,\nyou can use this documentation to integrate the optimizations into <em>FlagGems</em>\u2026</p>", "a[href=\"#initialize-the-directory\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. Initialize the directory<a class=\"headerlink\" href=\"#initialize-the-directory\" title=\"Link to this heading\">#</a></h2><p>Create the necessary files, including but not limited to the <code class=\"docutils literal notranslate\"><span class=\"pre\">__init__.py</span></code> file,\nthe <code class=\"docutils literal notranslate\"><span class=\"pre\">heuristics_config_utils.py</span></code> file, the <code class=\"docutils literal notranslate\"><span class=\"pre\">tune_configs.yaml</span></code> file , as well as a folder named  <code class=\"docutils literal notranslate\"><span class=\"pre\">ops</span></code>.\nThe expected directory layout is shown in the following example:</p>", "a[href=\"#adding-a-new-backend\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Adding a New Backend<a class=\"headerlink\" href=\"#adding-a-new-backend\" title=\"Link to this heading\">#</a></h1><h2>1. Introduction<a class=\"headerlink\" href=\"#introduction\" title=\"Link to this heading\">#</a></h2><p>The <code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems</span></code> accelerated operators library from the <em>FlagGems</em> project can be used on multiple backends.\nIf you are a chip vendor and wish to contribute backend-specific optimizations for your hardware,\nyou can use this documentation to integrate the optimizations into <em>FlagGems</em>\u2026</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
